import * as THREE from '../three.module.js';
export function groundMaterial(material,kind){material.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 groundWorld;\n'+shader.vertexShader.replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvec4 gw=vec4(transformed,1.0);\n#ifdef USE_INSTANCING\ngw=instanceMatrix*gw;\n#endif\ngroundWorld=(modelMatrix*gw).xyz;');shader.fragmentShader='varying vec3 groundWorld;\nfloat groundHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat groundNoise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(groundHash(i),groundHash(i+vec2(1,0)),f.x),mix(groundHash(i+vec2(0,1)),groundHash(i+vec2(1,1)),f.x),f.y);}\n'+shader.fragmentShader;const detail=kind==='grass'?`vec2 gp=groundWorld.xz;float macro=groundNoise(gp*.28);float micro=groundNoise(gp*95.0);float mow=sin(gp.x*.40)*.022;float worn=smoothstep(.65,.9,groundNoise(gp*.7));diffuseColor.rgb*=.85+.23*macro+.08*micro+mow;diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.27,.28,.12),worn*.19);`:`vec2 gp=groundWorld.xz;float macro=groundNoise(gp*1.7);float micro=groundNoise(gp*135.0);float footWear=exp(-pow((gp.y-.1)/1.2,2.0))+exp(-pow((gp.y+18.4)/1.0,2.0));diffuseColor.rgb*=.82+.27*macro+.08*micro-footWear*.055;`;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\n'+detail).replace('#include <normal_fragment_maps>','#include <normal_fragment_maps>\nfloat grainNormal=groundNoise(groundWorld.xz*65.0);normal=normalize(normal+vec3(dFdx(grainNormal),dFdy(grainNormal),0.0)*.11);');};material.customProgramCacheKey=()=>kind+'-ground-physical01';return material;}
export class GroundSurfaceController {
 constructor(scene){this.scene=scene;let seed=614;const rand=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};const vertices=[];for(let i=0;i<70;i++){let x=(rand()-.5)*2.8,z=-19+rand()*20;const len=.06+rand()*.3,angle=rand()*6.28;for(let j=0;j<3;j++){const nx=x+Math.sin(angle+j*.25)*len/3,nz=z+Math.cos(angle+j*.25)*len/3,width=.0015+rand()*.002;vertices.push(x-width,.026,z,x+width,.026,z,nx+width,.026,nz,x-width,.026,z,nx+width,.026,nz,nx-width,.026,nz);if(j===1){vertices.push(nx,.026,nz,nx+.04,.026,nz+.02,nx+.001,.026,nz+.003);}x=nx;z=nz;}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));g.computeVertexNormals();this.cracks=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:'#887a5d',roughness:1,transparent:true,opacity:.5,depthWrite:false}));scene.add(this.cracks);
 this.wear=new THREE.InstancedMesh(new THREE.CircleGeometry(.085,10),new THREE.MeshBasicMaterial({color:'#958467',transparent:true,opacity:.16,depthWrite:false}),120);this.wear.count=0;this.wear.rotation.x=-Math.PI/2;scene.add(this.wear);this.wearIndex=0;this.dummy=new THREE.Object3D();
 const dustGeom=new THREE.BufferGeometry();dustGeom.setAttribute('position',new THREE.Float32BufferAttribute(new Float32Array(24),3));this.dust=new THREE.Points(dustGeom,new THREE.PointsMaterial({color:'#c4b58c',size:.017,transparent:true,opacity:0,depthWrite:false}));scene.add(this.dust);this.dustAge=1;
 this.ballShadow=new THREE.Mesh(new THREE.CircleGeometry(.04,20),new THREE.MeshBasicMaterial({color:'#14291b',transparent:true,opacity:.3,depthWrite:false}));this.ballShadow.rotation.x=-Math.PI/2;scene.add(this.ballShadow);this.age=0;}
 footprint(foot){const i=this.wearIndex++%120;this.dummy.position.set(foot.x,-foot.z,.028);this.dummy.rotation.set(0,0,.2);this.dummy.scale.set(.75,1.8,1);this.dummy.updateMatrix();this.wear.setMatrixAt(i,this.dummy.matrix);this.wear.count=Math.min(120,this.wearIndex);this.wear.instanceMatrix.needsUpdate=true;this.cracks.material.opacity=Math.min(.76,.5+this.wearIndex*.002);}
  getPitchSurfaceState(x, z){
    const distFrontCrease = Math.abs(z - 1.0), distBackCrease = Math.abs(z + 18.4);
    const inCreaseZone = (distFrontCrease < 1.8 || distBackCrease < 1.8) && Math.abs(x) < 1.0;
    const wearFactor = Math.min(1.0, (this.wearIndex * 0.005) + (inCreaseZone ? 0.25 : 0.0));
    return { wearFactor, restitutionMult: 1.0 - (wearFactor * 0.08), frictionMult: 1.0 + (wearFactor * 0.15), seamKick: wearFactor * 0.025 };
  }
 event(event){if(event.type==='BallPitched'){this.dustOrigin={...event.position};this.dustAge=0;}}
 update(dt,ball){this.age+=dt;this.dustAge+=dt;if(this.dustOrigin&&this.dustAge<.22){const a=this.dust.geometry.attributes.position;for(let i=0;i<8;i++){const angle=i*2.4;a.setXYZ(i,this.dustOrigin.x+Math.sin(angle)*this.dustAge*.15,.03+this.dustAge*.25,this.dustOrigin.z+Math.cos(angle)*this.dustAge*.15);}a.needsUpdate=true;this.dust.material.opacity=(1-this.dustAge/.22)*.22;}else this.dust.material.opacity=0;this.ballShadow.visible=ball.y>0&&ball.y<8;this.ballShadow.position.set(ball.x,.029,ball.z);this.ballShadow.scale.setScalar(1+Math.max(0,ball.y)*.35);this.ballShadow.material.opacity=.30/(1+Math.max(0,ball.y)*.55);}
}
